/**
 * AuctionBriefing.tsx
 * The pre-auction briefing every franchise must read and acknowledge (rule 7).
 *
 * Shown in place of the waiting room and the bidding station to any franchise
 * that has not acknowledged the room's *current* rules. The room enforces the
 * same gate server-side -- a bid, fold or buffer from an unbriefed franchise is
 * refused -- so this screen is the explanation of a rule, not the rule itself.
 *
 * Nothing on it is hardcoded. The figures come from `state.rules` and the list
 * from `state.briefing`, both generated by the room from the rules it enforces,
 * so a host's setup change re-renders this screen with the new numbers in the
 * same frame that changes them.
 */
import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

import type { AuctionSocket } from "../../hooks/useAuctionSocket";

const EASE = [0.16, 1, 0.3, 1] as const;

function crore(lakh: number | undefined): string {
  if (lakh == null) return "—";
  const cr = lakh / 100;
  return `₹${Number.isInteger(cr) ? cr : cr.toFixed(2)} Cr`;
}

export interface AuctionBriefingProps {
  socket: AuctionSocket;
  onLeave: () => void;
}

export default function AuctionBriefing({ socket, onLeave }: AuctionBriefingProps) {
  const reduced = useReducedMotion();
  const [read, setRead] = useState(false);
  const { state, myTeam } = socket;
  const rules = state?.rules;
  const items = state?.briefing ?? [];

  const tiles = rules
    ? [
        { label: "Total budget", value: crore(rules.purse), note: "same for every franchise", key: true },
        {
          label: "Minimum overseas",
          value: String(rules.min_overseas ?? 0),
          note: `at most ${rules.max_overseas} overseas`,
          key: true,
        },
        {
          label: "Minimum uncapped",
          value: String(rules.min_uncapped ?? 1),
          note: "at least one uncapped player",
          key: true,
        },
        {
          label: "Squad size",
          value: `${rules.min_squad}–${rules.max_squad}`,
          // Offline rooms have no clock, so no buffers to spend.
          note:
            rules.mode === "offline"
              ? "placards in the room, no clock"
              : `${rules.timeouts_per_team} decision buffers each`,
          key: false,
        },
      ]
    : [];

  return (
    <div className="grid min-h-screen place-items-center bg-surface bg-dots px-5 py-10">
      <div className="w-full max-w-3xl">
        <header className="mb-6 text-center">
          <span className="font-ui text-[9.5px] font-semibold uppercase tracking-[0.16em] text-slate-faint">
            AUCTONIQ · pre-auction briefing{myTeam ? ` · ${myTeam.name}` : ""}
          </span>
          <h1 className="mt-1.5 font-head text-[30px] font-bold leading-tight text-slate-ink">
            Read before you bid
          </h1>
          <p className="mt-2 font-ui text-[12.5px] text-slate-muted">
            These rules apply identically to every franchise in the room. You can bid only after you
            acknowledge them.
          </p>
        </header>

        {socket.rulesChanged && (
          <div
            role="status"
            className="mb-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-2.5 text-center font-ui text-[12px] font-semibold text-amber-800"
          >
            The auctioneer updated the rules. Review the changes and acknowledge again to keep bidding.
          </div>
        )}

        {/* The three constraints the briefing must lead with, then squad size. */}
        <section aria-label="Key auction figures" className="grid grid-cols-2 gap-2.5 sm:grid-cols-4">
          {tiles.map((tile, index) => (
            <motion.div
              key={tile.label}
              initial={reduced ? false : { opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.25, ease: EASE, delay: index * 0.04 }}
              className={`rounded-xl border p-3.5 shadow-soft ${
                tile.key ? "border-slate-ink/20 bg-surface-card" : "border-line bg-surface-card"
              }`}
            >
              <div className="font-ui text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-muted">
                {tile.label}
              </div>
              <div className="mt-1 font-num text-[28px] font-bold leading-none text-slate-ink">
                {tile.value}
              </div>
              <div className="mt-1.5 font-ui text-[11px] text-slate-muted">{tile.note}</div>
            </motion.div>
          ))}
        </section>

        <section
          aria-labelledby="briefing-rules"
          className="mt-4 rounded-xl border border-line bg-surface-card p-5 shadow-soft"
        >
          <div className="mb-3 flex items-baseline justify-between">
            <h2
              id="briefing-rules"
              className="font-ui text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-muted"
            >
              Auction rules
            </h2>
            <span className="font-ui text-[10px] uppercase tracking-[0.1em] text-slate-faint">
              rules v{state?.rules_version ?? "—"}
            </span>
          </div>

          <ol className="space-y-3">
            {items.map((item, index) => (
              <motion.li
                key={item.id}
                initial={reduced ? false : { opacity: 0, x: -6 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.25, ease: EASE, delay: 0.1 + index * 0.04 }}
                className="flex gap-3"
              >
                <span
                  aria-hidden
                  className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-slate-ink font-num text-[12px] font-bold text-white"
                >
                  {index + 1}
                </span>
                <div>
                  <div className="font-ui text-[13.5px] font-semibold text-slate-ink">{item.title}</div>
                  <p className="mt-0.5 font-ui text-[13px] leading-relaxed text-slate-body">{item.body}</p>
                </div>
              </motion.li>
            ))}
            {items.length === 0 && (
              <li className="font-ui text-[13px] text-slate-muted">Loading the room's rules…</li>
            )}
          </ol>
        </section>

        <div className="mt-5 flex flex-col items-center gap-3">
          <label className="flex cursor-pointer items-center gap-2.5 font-ui text-[13px] text-slate-body">
            <input
              type="checkbox"
              checked={read}
              onChange={(event) => setRead(event.target.checked)}
              className="h-4 w-4 accent-slate-900"
            />
            I have read the briefing and agree to bid under these rules.
          </label>

          <div className="flex items-center gap-3">
            <button
              type="button"
              data-testid="acknowledge-briefing"
              disabled={!read || socket.status !== "open" || items.length === 0}
              onClick={socket.acknowledgeRules}
              className="min-h-[44px] rounded-lg border border-slate-ink bg-slate-ink px-5 py-2.5 font-ui text-[11px] font-semibold uppercase tracking-[0.14em] text-white transition-colors hover:bg-slate-ink/90 disabled:cursor-not-allowed disabled:border-line disabled:bg-surface-sunken disabled:text-slate-faint"
            >
              Acknowledge &amp; enter the room
            </button>
            <button
              type="button"
              onClick={onLeave}
              className="min-h-[44px] rounded-lg border border-line bg-surface-card px-4 py-2.5 font-ui text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-muted hover:text-slate-ink"
            >
              Leave seat
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
